metadata:
{"id": "NE.IMP.GNFS.CN", "name": "Imports of goods and services (current LCU)", "unit": "", "source": {"id": "2", "value": "World Development Indicators"}, "sourceNote": "Imports of goods includes change in the economic ownership of goods from non-residents to




residents of the compiling economy, irrespective of physical movement of goods across national borders. Imports of services includes services provided by non-residents to residents. This indicator is expressed in current prices, meaning no adjustment has been made to account for price changes over time. This series is expressed in local currency units.", "sourceOrganization": "Country official statistics, National Statistical Offices (NSOs);
National Accounts data files, Central Banks;
Staff estimates, World Bank (WB)", "topics": [{"id": "3", "value": "Economy & Growth"}]}

{"id": "NE.IMP.GNFS.KN", "name": "Imports of goods and services (constant LCU)", "unit": "", "source": {"id": "2", "value": "World Development Indicators"}, "sourceNote": "Imports of goods includes change in the economic ownership of goods from non-residents to




residents of the compiling economy, irrespective of physical movement of goods across national borders. Imports of services includes services provided by non-residents to residents. This indicator is expressed in constant prices, meaning the series has been adjusted to account for price changes over time. The reference year for this adjustment varies by country. This series is expressed in local currency units.", "sourceOrganization": "Country official statistics, National Statistical Offices (NSOs);
National Accounts data files, Central Banks;
Staff estimates, World Bank (WB)", "topics": [{"id": "3", "value": "Economy & Growth"}]}

{"id": "SP.POP.TOTL", "name": "Population, total", "unit": "", "source": {"id": "2", "value": "World Development Indicators"}, "sourceNote": "Total population is based on the de facto definition of population, which counts all residents regardless of legal status or citizenship. The values shown are midyear estimates.", "sourceOrganization": "World Population Prospects, United Nations (UN), uri: https://population.un.org/wpp/, publisher: UN Population Division;
Statistical databases and publications from national statistical offices, National Statistical Offices (NSOs), uri: https://unstats.un.org/home/nso_sites/, publisher: National Statistical Offices;
Eurostat: Demographic Statistics, Eurostat (ESTAT), uri: https://ec.europa.eu/eurostat/data/database?node_code=earn_ses_monthly, publisher: Eurostat;
Population and Vital Statistics Report (various years), United Nations (UN), uri: https://unstats.un.org, publisher: UN Statistics Division", "topics": [{"id": "19", "value": "Climate Change"}, {"id": "8", "value": "Health "}]}

{"id": "NY.GNS.ICTR.CN", "name": "Gross savings (current LCU)", "unit": "", "source": {"id": "2", "value": "World Development Indicators"}, "sourceNote": "Savings is an amount that represents the part of disposable income (adjusted for the








change in pension entitlements) that is not spent on final consumption. Gross savings are calculated as gross national income less total consumption, plus net transfers. This indicator is expressed in current prices, meaning no adjustment has been made to account for price changes over time. This series is expressed in local currency units.", "sourceOrganization": "Country official statistics, National Statistical Offices (NSOs);
National Accounts data files, Central Banks;
Staff estimates, World Bank (WB)", "topics": [{"id": "3", "value": "Economy & Growth"}]}

{"id": "SP.DYN.CBRT.IN", "name": "Birth rate, crude (per 1,000 people)", "unit": "", "source": {"id": "2", "value": "World Development Indicators"}, "sourceNote": "Crude birth rate indicates the number of live births occurring during the year, per 1,000 population estimated at midyear. Subtracting the crude death rate from the crude birth rate provides the rate of natural increase, which is equal to the rate of population change in the absence of migration.", "sourceOrganization": "World Population Prospects, United Nations (UN), publisher: UN Population Division;
Statistical databases and publications from national statistical offices, National Statistical Offices (NSOs);
Demographic Statistics, Eurostat (ESTAT);
Population and Vital Statistics Report (various years), United Nations (UN), publisher: UN Statistical Division", "topics": [{"id": "8", "value": "Health "}]}

{"id": "SP.DYN.CDRT.IN", "name": "Death rate, crude (per 1,000 people)", "unit": "", "source": {"id": "2", "value": "World Development Indicators"}, "sourceNote": "Crude death rate indicates the number of deaths occurring during the year, per 1,000 population estimated at midyear. Subtracting the crude death rate from the crude birth rate provides the rate of natural increase, which is equal to the rate of population change in the absence of migration.", "sourceOrganization": "World Population Prospects, United Nations (UN), publisher: UN Population Division;
Statistical databases and publications from national statistical offices, National Statistical Offices (NSOs);
Demographic Statistics, Eurostat (ESTAT);
Population and Vital Statistics Report (various years), United Nations (UN), publisher: UN Statistical Division", "topics": [{"id": "8", "value": "Health "}]}
